import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const z=JSON.parse('{"title":"初放","description":"","frontmatter":{"title":"初放","date":"2026-11-24T00:00:00.000Z","seq":31,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"东方朔","source_book":"楚辞","prev":{"text":"招隐士","link":"/blogs/楚辞/招隐士.html"},"next":{"text":"沉江","link":"/blogs/楚辞/沉江.html"}},"headers":[],"relativePath":"blogs/楚辞/初放.md","filePath":"blogs/楚辞/初放.md"}'),o={name:"blogs/楚辞/初放.md"};function l(n,a,c,m,r,_){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="初放" tabindex="-1">初放 <a class="header-anchor" href="#初放" aria-label="Permalink to &quot;初放&quot;">​</a></h1><p class="poem-meta">先秦 · 东方朔　·　七谏</p><div class="poem"><p class="poem-stanza">平生于国兮，长于原野。</p><p class="poem-stanza">言语讷譅兮，又无彊辅。</p><p class="poem-stanza">浅智褊能兮，闻见又寡。</p><p class="poem-stanza">数言便事兮，见怨门下。</p><p class="poem-stanza">王不察其长利兮，卒见弃乎原野。</p><p class="poem-stanza">伏念思过兮，无可改者。</p><p class="poem-stanza">群众成朋兮，上浸以惑。</p><p class="poem-stanza">巧佞在前兮，贤者灭息。</p><p class="poem-stanza">尧、舜圣已没兮，孰为忠直？</p><p class="poem-stanza">高山崔巍兮，水流汤汤。</p><p class="poem-stanza">死日将至兮，与麋鹿同坑。</p><p class="poem-stanza">塊兮鞠，当道宿，举世皆然兮，余将谁告？</p><p class="poem-stanza">斥逐鸿鹄兮，近习鸱枭，斩伐橘柚兮，列树苦桃。</p><p class="poem-stanza">便娟之修竹兮，寄生乎江潭。</p><p class="poem-stanza">上葳蕤而防露兮，下泠泠而来风。</p><p class="poem-stanza">孰知其不合兮，若竹柏之异心。</p><p class="poem-stanza">往者不可及兮，来者不可待。</p><p class="poem-stanza">悠悠苍天兮，莫我振理。</p><p class="poem-stanza">窃怨君之不寤兮，吾独死而後已。</p></div>',3)])])}const d=s(o,[["render",l]]);export{z as __pageData,d as default};
